mapper.select:
select document_id, document_name, document_type, knowledge_version, source_type, source_name, document_status, enabled, create_time, update_time from knowledge_document
document_status = #{status}
order by update_time asc, id asc
order by update_time desc, id desc
limit #{limit}

mapper.update:
update knowledge_document
set document_status = #{documentStatus},
    enabled = #{enabled},
    update_time = #{updateTime}
where document_id = #{documentId}
